import {proofDetails,proofProgress,proofStatus} from './proof-model.js';
import {validateTree,treeView,lineage,layoutTree} from './tree-model.js';
import {validateCollection,matchingMilestones,focusContext} from './collection-model.js';
import {safeUrl,validateEvidence,filterResults,proposal,validateDesk} from './evidence-model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label,cls='')=>{const local=typeof url==='string'&&/^\/sources\/[^/]+$/.test(url);const href=local?url:safeUrl(url);return href?`<a href="${esc(href)}" class="${cls}" target="_blank" rel="noopener noreferrer">${label}</a>`:esc(label);};
const colors={AI:'var(--ai)',Robotics:'var(--robot)',Materials:'var(--material)',Longevity:'var(--life)'},icons={AI:'✳',Robotics:'⌘',Materials:'◈',Longevity:'❋'};
const KEY='techtree-evidence-desk-v2',browserKeys=[KEY,'techtree-state-v1'];
async function api(path,options={}){const response=await fetch(path,{cache:'no-store',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});const result=await response.json();if(!response.ok){const error=new Error(result.message||'Local database request failed');error.status=response.status;throw error;}return result;}
let bootstrap;try{bootstrap=await api('/api/bootstrap');}catch(error){$('#app').textContent='TechTree could not load its local database: '+error.message+'. Start the local server with npm start, then reload.';throw error;}
let desk=validateDesk(bootstrap.desk),dbActivity=bootstrap.activity,storageError='',migrationReports=[];
let retainedBrowserSnapshots=[];
try{retainedBrowserSnapshots=browserKeys.map(key=>({key,raw:localStorage.getItem(key)})).filter(s=>s.raw!==null);}catch{storageError='Browser storage is unavailable. The SQLite database remains available; browser-save migration could not be checked.';}
if(retainedBrowserSnapshots.length){try{const migrated=await api('/api/migrate-browser',{method:'POST',body:JSON.stringify({snapshots:retainedBrowserSnapshots})});desk=validateDesk(migrated.desk);dbActivity=await api('/api/activity');migrationReports=migrated.reports;if(migrated.conflicts||migrationReports.some(r=>r.issues.length))storageError='Browser saves were retained in SQLite with records needing review. No conflicting copy was overwritten. Open Research desk for the migration report.';}catch(error){storageError='Browser-save import could not finish: '+error.message+'. Original browser copies are unchanged.';}}
const migrationStatus=await api('/api/migrations');
async function refreshDesk(){const [saved,activity]=await Promise.all([api('/api/desk'),api('/api/activity')]);desk=validateDesk(saved);dbActivity=activity;}
let tab='tree',domain='All fields',query='',kind='all',selected='EV-AF',layout='grouped';
const data=bootstrap.evidence;validateEvidence(data);
const shortDate=date=>new Intl.DateTimeFormat('en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(`${date}T12:00:00Z`));
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000);}

function download(content,name){const u=URL.createObjectURL(new Blob([JSON.stringify(content,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500);}
function sourceBlock(r){const s=r.source;return `<div class="claim-source"><span class="card-label">PRIMARY SOURCE</span>${link(s.url,`${esc(s.title)} ↗`,'paper-title')}<div class="source-date">${esc(s.dateLabel)} · <time datetime="${s.published}">${shortDate(s.published)}</time>${s.version?`<br>${esc(s.version)}`:''}</div>${link(s.url,esc(s.url),'source-url')}${s.correction?`<div class="correction-note">${link(s.correction.url,`${esc(s.correction.title)} · ${shortDate(s.correction.published)} ↗`)}<p>${esc(s.correction.note)}</p></div>`:''}</div>`;}
function card(r,i=0){return `<article class="result-card ${r.id===selected?'chosen':''}" data-result="${r.id}" style="--accent:${colors[r.domain]};--delay:${i*35}ms"><div class="result-card-top"><span><i class="dot"></i>${esc(r.kind)}</span><span>${esc(r.id)}</span></div><button class="result-title" data-select="${r.id}" aria-pressed="${r.id===selected}">${esc(r.title)}<span>↗</span></button><div class="claim-copy"><span class="card-label">REPORTED FINDING</span><p>${esc(r.claim)}</p></div><div class="claim-limit"><span class="card-label">LIMITS OF THIS EVIDENCE</span><p>${esc(r.limitations)}</p></div>${sourceBlock(r)}</article>`;}
let sourceAudit=bootstrap.sourceAudit;
const collection=bootstrap.collection;validateCollection(collection,data);
let field='Machine Learning',milestoneQuery='',fieldQuery='',evidenceOnly=false,duplicatesOnly=false,selectedMilestone='ROB-01',collectionMode='browse',showHypotheses=false,pageNumber=0;
const pageSize=20,associationNames={'partial-evidence':'Partial evidence','related-evidence':'Related evidence','qualification':'Limits / qualification','challenging-evidence':'Challenging evidence'};
const fieldColor=f=>f==='Machine Learning'?'var(--ai)':f==='Robotics'?'var(--robot)':f==='Material Science'||f==='Crystallography'?'var(--material)':f==='Longevity'||f==='Biochemistry'?'var(--life)':'var(--green)';
function milestoneName(id){return collection.milestones.find(m=>m.id===id)?.title||id;}
function jumpMilestone(id,mode=collectionMode){if(mode==='map'){openTreeNode(id,{lineageView:true});return;}const m=collection.milestones.find(m=>m.id===id);if(!m)return;selectedMilestone=id;field=m.field;milestoneQuery='';evidenceOnly=false;duplicatesOnly=false;pageNumber=0;collectionMode=mode;tab='milestones';render();}
function fieldOptions(){return `<option value="All fields" ${field==='All fields'?'selected':''}>All 66 fields · 660 milestones</option>${[...new Set(collection.fields.map(f=>f.category))].sort().map(cat=>`<optgroup label="${esc(cat)}">${collection.fields.filter(f=>f.category===cat).map(f=>`<option value="${esc(f.name)}" ${field===f.name?'selected':''}>${esc(f.name)} (${f.count})</option>`).join('')}</optgroup>`).join('')}`;}
function milestoneCard(m){const attached=collection.evidenceAssociations.filter(a=>a.milestoneId===m.id);return `<article class="milestone-card ${m.id===selectedMilestone?'chosen':''}" data-milestone-card="${m.id}" style="--accent:${fieldColor(m.field)}"><div class="milestone-meta"><span>${m.id} / ${esc(m.field)}</span><span class="proposal-badge">Proposed milestone</span></div><button class="milestone-title" data-milestone="${m.id}">${esc(m.title)}<span>↗</span></button><p class="original-excerpt">${esc(m.description)}</p><div class="milestone-card-bottom"><span>${esc(proofStatus(sourceAudit,m.id))}</span>${m.duplicateOf?`<button data-jump="${m.duplicateOf}" class="duplicate-tag">Source duplicate → ${m.duplicateOf}</button>`:''}<button data-focus="${m.id}">Focus map ↗</button></div></article>`;}
function associationCard(a){const r=data.results.find(r=>r.id===a.resultId);return `<article class="attached-evidence" data-association="${a.id}"><div class="attachment-heading"><span class="eyebrow">${associationNames[a.kind]} / ${r.id}</span><span>Does not establish milestone</span></div><h4>${esc(r.title)}</h4><span class="card-label">WHAT THE RESEARCH REPORTS</span><p>${esc(r.claim)}</p><div class="claim-limit"><span class="card-label">RESEARCH LIMITATIONS</span><p>${esc(r.limitations)}</p></div><div class="relevance-block"><span class="card-label">OUR INTERPRETATION OF RELEVANCE</span><p>${esc(a.relevance)}</p><p class="boundary">${esc(a.boundary)}</p></div>${sourceBlock(r)}<details class="provenance-fold"><summary>Review scope and provenance</summary><p>${esc(r.scope)}<br>${esc(r.source.locator)}<br>${esc(r.source.checkMethod)}<br>${esc(a.provenance.basis)}</p></details></article>`;}
function relationshipCard(r,direction){const id=direction==='upstream'?r.fromId:r.toId;return `<article class="hypothesis-card"><span class="eyebrow">HYPOTHESIS · POSSIBLE ACCELERATOR</span><button data-jump="${id}" class="relationship-title">${id} / ${esc(milestoneName(id))} ↗</button><p>${esc(r.rationale)}</p><div class="claim-limit"><span class="card-label">UNCERTAINTY</span><p>${esc(r.uncertainty)}</p></div><p class="relation-provenance">${esc(r.provenance.origin)} · ${esc(r.provenance.checkedAt)}<br>${esc(r.provenance.sourceLocator)}</p>${r.resultIds.map(id=>{const s=data.results.find(s=>s.id===id).source;return link(s.url,`${esc(s.title)} ↗`,'source-link')}).join('')}<small>Source motivates this interpretation; it does not verify the proposed dependency.</small></article>`;}
function focusedMap(){const context=focusContext(collection,selectedMilestone,{showHypotheses}),m=context.milestone;return `<section class="focus-board" aria-label="Focused milestone map"><div class="focus-heading"><span class="eyebrow">ONE MILESTONE / ITS EVIDENCE AND POSSIBLE CONNECTIONS</span><label class="checkbox"><input type="checkbox" id="show-hypotheses" ${showHypotheses?'checked':''}>Show proposed links</label></div><p class="focus-explainer">Evidence attachments show relevance, not prerequisites. Dashed connectors appear only for the explicitly labeled hypotheses when enabled.</p><section class="focus-row"><h3>Upstream possibilities</h3>${context.upstream.length?context.upstream.map(r=>relationshipCard(r,'upstream')).join('')+`<div class="hypothesis-connector" aria-label="Hypothetical accelerator, not established dependency">⋮<br>could accelerate ↓</div>`:`<div class="unmapped">${showHypotheses?'No upstream links reviewed for this milestone.':'Proposed links hidden. No established upstream dependencies have been reviewed.'}</div>`}</section><div class="focus-target" style="--accent:${fieldColor(m.field)}"><span class="eyebrow">${m.id} / ORIGINAL PROPOSED MILESTONE</span><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p><span class="proposal-badge">Achievement not assessed</span></div><section class="focus-row"><h3>Downstream possibilities</h3>${context.downstream.length?`<div class="hypothesis-connector">could accelerate ↓<br>⋮</div>`+context.downstream.map(r=>relationshipCard(r,'downstream')).join(''):`<div class="unmapped">${showHypotheses?'No downstream links reviewed for this milestone.':'Proposed links hidden. No established downstream dependencies have been reviewed.'}</div>`}</section><section class="focus-row"><h3>Research evidence attached <span>${context.evidence.length}</span></h3>${context.evidence.length?context.evidence.map(associationCard).join(''):'<div class="unmapped">No checked research result has been attached yet. This says nothing about whether relevant research exists.</div>'}</section></section>`;}
function originalDetail(){const c=focusContext(collection,selectedMilestone,{showHypotheses:true}),m=c.milestone;return `<div class="detail-inner original-detail" style="--accent:${fieldColor(m.field)}"><div class="detail-top"><span>${m.id} / ${esc(m.field)}</span><span>↗</span></div><h2>${esc(m.title)}</h2><span class="proposal-badge">Original proposal · not verified achieved</span><h3>Original description</h3><p class="original-full">${esc(m.description)}</p><h3>Original impact assertion</h3><p class="original-full">${esc(m.impact)}</p><p class="source-assertion-note">Original wording is preserved, including ambitious or absolute language. These are source assertions and aspirations, not verified outcomes or endorsed guarantees.</p>${proofDetails(m,sourceAudit)}<h3>Additional study associations / ${c.evidence.length}</h3>${c.evidence.length?c.evidence.map(a=>`<button class="detail-evidence-link" data-evidence-focus="${m.id}">${associationNames[a.kind]} · ${esc(data.results.find(r=>r.id===a.resultId).title)} ↗</button>`).join(''):'<p>No additional curated study attached.</p>'}<button class="secondary" data-focus="${m.id}">Explore focused map →</button><h3>Dependency review</h3><p>${c.upstream.length+c.downstream.length?`${c.upstream.length+c.downstream.length} possible accelerator ${c.upstream.length+c.downstream.length===1?'hypothesis':'hypotheses'} available in Focus map. No established dependency is asserted.`:'Dependencies have not been reviewed for this milestone. No legacy prerequisite has been accepted.'}</p>${c.duplicates.length?`<h3>Duplicate flags from source</h3><p>All entries remain distinct and browsable. The source flags:</p>${c.duplicates.map(d=>`<button class="duplicate-detail" data-jump="${d.id}">${m.duplicateOf===d.id?'Canonical reference':'Source duplicate'} → ${d.id}<br>${esc(d.title)}</button>`).join('')}${m.duplicateProvenance?`<p>${esc(m.duplicateProvenance.rationale)}<br>Source: Deduplication row ${m.duplicateProvenance.row}</p>`:''}`:''}<details class="provenance-fold"><summary>Original entry identity</summary><p>Stable source ID: ${m.id}<br>Original notes text is preserved above.</p></details></div>`;}
function collectionView(){const matches=matchingMilestones(collection,{field,query:milestoneQuery,evidenceOnly,duplicatesOnly});const page=matches.slice(pageNumber*pageSize,(pageNumber+1)*pageSize);const filteredFields=collection.fields.filter(f=>`${f.name} ${f.category}`.toLowerCase().includes(fieldQuery.toLowerCase()));const categories=[...new Set(filteredFields.map(f=>f.category))].sort();return `<main class="workspace collection-workspace"><div class="toolbar collection-toolbar"><div class="collection-title"><span class="eyebrow">YOUR ORIGINAL COLLECTION</span><strong>${field==='All fields'?'All fields of study':esc(field==='Machine Learning'?'Artificial intelligence / Machine Learning':field)}</strong></div><div class="tools"><label class="searchbox"><span aria-hidden="true">⌕</span><input id="milestone-search" aria-label="Search original milestones" placeholder="Search titles, ideas or IDs…" value="${esc(milestoneQuery)}"></label><label class="checkbox tool-check"><input id="evidence-only" type="checkbox" ${evidenceOnly?'checked':''}>With evidence</label><label class="checkbox tool-check"><input id="duplicates-only" type="checkbox" ${duplicatesOnly?'checked':''}>Source duplicates</label></div></div><div class="mobile-field-picker"><label>Field of study<select id="mobile-field">${fieldOptions()}</select></label></div><div class="collection-layout"><aside class="field-directory" aria-label="Fields of study"><div class="directory-heading"><span>EXPLORE BY FIELD</span><b>66</b></div><input id="field-search" aria-label="Find a field of study" placeholder="Find a field…" value="${esc(fieldQuery)}"><button class="field-button ${field==='All fields'?'active':''}" data-field="All fields">All fields <span>660</span></button><div class="field-groups">${categories.map(cat=>`<section class="field-group"><h3>${esc(cat)}</h3>${filteredFields.filter(f=>f.category===cat).map(f=>`<button class="field-button ${field===f.name?'active':''}" data-field="${esc(f.name)}" title="${esc(f.name)}">${esc(f.name)} <span>${f.count}</span></button>`).join('')}</section>`).join('')}${!filteredFields.length?'<p class="directory-empty">No matching field.</p>':''}</div></aside><section class="collection-main"><div class="collection-viewbar"><span>${matches.length} ORIGINAL ${matches.length===1?'MILESTONE':'MILESTONES'}${field==='All fields'?' / 66 FIELDS':''}</span><div class="view-switch" aria-label="Collection view"><button data-mode="browse" class="${collectionMode==='browse'?'active':''}">Browse</button><button data-mode="map" class="${collectionMode==='map'?'active':''}">Focus map</button></div></div>${collectionMode==='browse'?`<div class="milestone-list">${page.map(milestoneCard).join('')}${!page.length?'<div class="empty">No milestones match.<br><button class="secondary" id="clear-milestones">Clear search and filters</button></div>':''}</div>${matches.length>pageSize?`<div class="pagination"><button id="previous-page" class="secondary" ${pageNumber===0?'disabled':''}>← Previous</button><span>${pageNumber*pageSize+1}–${Math.min((pageNumber+1)*pageSize,matches.length)} of ${matches.length}</span><button id="next-page" class="secondary" ${(pageNumber+1)*pageSize>=matches.length?'disabled':''}>Next →</button></div>`:''}`:matches.length?focusedMap():'<div class="empty">No milestones match the current search and filters.</div>'}</section><aside class="detail collection-detail" aria-label="Original milestone details">${originalDetail()}</aside></div></main><section class="insight-strip"><span class="insight-mark">↳</span><div><h3>Your milestones are the foundation. Research is the evidence layer.</h3><p>All 660 original proposals remain intact across 66 fields. Nine checked studies provide ten evidence attachments to nine milestones. Two optional links are accelerator hypotheses; no established dependency has been reviewed. The broken legacy relationship map is excluded.</p></div><button data-tab="changes">See collection history ↗</button></section>`;}
function setField(next){field=next;milestoneQuery='';pageNumber=0;const matches=matchingMilestones(collection,{field,query:milestoneQuery,evidenceOnly,duplicatesOnly});if(matches.length&&!matches.some(m=>m.id===selectedMilestone))selectedMilestone=matches[0].id;render();}
function collectionBind(){
 document.querySelectorAll('[data-field]').forEach(b=>b.onclick=()=>setField(b.dataset.field));if($('#mobile-field'))$('#mobile-field').onchange=e=>setField(e.target.value);
 for(const [selector,assign] of [['#field-search',v=>fieldQuery=v],['#milestone-search',v=>{milestoneQuery=v;if(v.trim())field='All fields';pageNumber=0;const matches=matchingMilestones(collection,{field,query:v,evidenceOnly,duplicatesOnly});if(matches.length&&!matches.some(m=>m.id===selectedMilestone))selectedMilestone=matches[0].id;}]])if($(selector))$(selector).oninput=e=>{const pos=e.target.selectionStart;assign(e.target.value);render();$(selector).focus();$(selector).setSelectionRange(pos,pos)};
 if($('#evidence-only'))$('#evidence-only').onchange=e=>{evidenceOnly=e.target.checked;pageNumber=0;const ms=matchingMilestones(collection,{field,query:milestoneQuery,evidenceOnly,duplicatesOnly});if(ms.length&&!ms.some(m=>m.id===selectedMilestone))selectedMilestone=ms[0].id;render()};if($('#duplicates-only'))$('#duplicates-only').onchange=e=>{duplicatesOnly=e.target.checked;pageNumber=0;const ms=matchingMilestones(collection,{field,query:milestoneQuery,evidenceOnly,duplicatesOnly});if(ms.length&&!ms.some(m=>m.id===selectedMilestone))selectedMilestone=ms[0].id;render()};
 document.querySelectorAll('[data-milestone]').forEach(b=>b.onclick=()=>{selectedMilestone=b.dataset.milestone;const y=scrollY;render();window.scrollTo(0,y)});
 document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>jumpMilestone(b.dataset.jump));document.querySelectorAll('[data-focus],[data-evidence-focus]').forEach(b=>b.onclick=()=>jumpMilestone(b.dataset.focus||b.dataset.evidenceFocus,'map'));
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.mode==='map'){openTreeNode(selectedMilestone,{lineageView:true});return;}collectionMode='browse';render()});if($('#show-hypotheses'))$('#show-hypotheses').onchange=e=>{showHypotheses=e.target.checked;render()};
 if($('#next-page'))$('#next-page').onclick=()=>{pageNumber++;render()};if($('#previous-page'))$('#previous-page').onclick=()=>{pageNumber--;render()};if($('#clear-milestones'))$('#clear-milestones').onclick=()=>{milestoneQuery='';evidenceOnly=false;duplicatesOnly=false;pageNumber=0;render()};
 if($('#export-collection'))$('#export-collection').onclick=()=>download(collection,'techtree-original-collection.json');
}
function collectionHistory(){return `<main class="page-content"><div class="view-actions"><span class="eyebrow">COLLECTION HISTORY</span><button class="secondary" id="export-collection">Export milestone collection</button><button class="secondary" id="export-desk">Export saved source suggestions</button></div><h2 class="section-title">The original collection, with inspectable webpage proof points.</h2>${proofProgress(sourceAudit)}<p>Original IDs, wording, descriptions, impact assertions and source provenance are preserved. Milestones are proposed ambitions; the cited research reports narrower results. No invented achievement dates or thresholds have been added.</p><div class="coverage-table"><table><thead><tr><th>Coverage</th><th>Current collection</th></tr></thead><tbody>${[['Original milestones',660],['Fields of study',66],['Source duplicate flags, entries retained',13],['Checked research results',9],['Evidence relevance attachments',10],['Original milestones with evidence attached',9],['Proposed tree arrows',tree.edges.length],['Original milestones connected',treeConnected.size],['Fields with curated connections',tree.reviewSummary?.connectedFields||24],['Remaining milestones reviewed',tree.reviewSummary?.reviewed||0],['Reviewed without a justified connection',tree.reviewSummary?.reviewedUnconnected||0],['Established dependency links',0],['Accepted legacy dependency rows',0]].map(([name,count])=>`<tr><th>${name}</th><td>${count}</td></tr>`).join('')}</tbody></table></div><div class="timeline">${collection.history.map(h=>`<article class="history-card"><span class="eyebrow">${esc(h.date)} / ${esc(h.id)}</span><h3>${esc(h.title)}</h3><p>${esc(h.description)}</p></article>`).join('')}</div><h3 class="subheading">Preserved browser history</h3><p>Source suggestions, review activity and revision records live in local SQLite. Earlier browser saves are imported idempotently and retained verbatim. Historical prototype records remain unverified and never become checked evidence.</p><button class="secondary" id="export-legacy">Export previous prototype proposals</button><h3 class="subheading">Database activity</h3>${databaseActivityView()}<h3 class="subheading">Connection review</h3><p>${tree.reviewSummary?.reviewed||0} of the 546 initially unconnected milestones received individual editorial dispositions. ${tree.reviewSummary?.reviewedUnconnected||0} remain without a justified connection. All new arrows are conceptual hypotheses derived from the original descriptions, without new scientific verification.</p><details><summary>Rejected and pruned proposals (${tree.reviewedCandidatesRejected?.length||0})</summary>${(tree.reviewedCandidatesRejected||[]).map(r=>`<p><b>${esc(r.fromId)} → ${esc(r.toId)}</b>: ${esc(r.reason)}</p>`).join('')}</details><h3 class="subheading">What remains scientifically unreviewed</h3><p>Most milestones have no evidence attached yet. Absence of an attachment is not evidence of absence. Field-document citations, source duplicate flags, impact assertions and achievement status have not been scientifically validated. The nine study checks retain their stated review depth; no full literature or independent replication audit is claimed.</p></main>`;}

const tree=bootstrap.tree;validateTree(tree,collection,data);
const treeConnected=new Set(tree.edges.flatMap(e=>[e.fromId,e.toId]));let treeBranch='manipulation',treeField=null,treeFocus=null,treeDepth=2,treeQuery='',selectedEdge=null,treeNeedFit=true,treeCamera={x:20,y:20,z:1},treeFilter='all';
const treeTypeLabel={enabling:'Possible enabling component',accelerator:'Possible accelerator','alternative-route':'Alternative research approach',feedback:'Possible iterative feedback',required:'Required in stated scope'};
function activeTreeView(){const v=treeView(tree,collection,{branch:treeBranch,field:treeField,focusId:treeFocus,depth:treeDepth});if(treeFilter==='all')return v;const edges=v.edges.filter(e=>e.kind===treeFilter),ids=new Set(edges.flatMap(e=>[e.fromId,e.toId]));if(!ids.size&&v.nodes.some(n=>n.id===selectedMilestone))ids.add(selectedMilestone);return {...v,edges,nodes:v.nodes.filter(n=>ids.has(n.id))};}
function treeNodeColor(n){return fieldColor(n.field);}
function openTreeNode(id,{lineageView=false}={}){selectedMilestone=id;selectedEdge=null;if(lineageView){treeFocus=id;treeField=null;treeNeedFit=true;}tab='tree';render();}
function treeEdgeDetail(){const e=tree.edges.find(e=>e.id===selectedEdge);if(!e)return '';return `<div class="edge-detail"><button id="close-edge" class="edge-close">× Close arrow details</button><span class="eyebrow">${e.id} / EDITORIAL HYPOTHESIS</span><h2>${treeTypeLabel[e.kind]}</h2><div class="edge-endpoints"><button data-tree-jump="${e.fromId}">${e.fromId} · ${esc(milestoneName(e.fromId))}</button><span>↓</span><button data-tree-jump="${e.toId}">${e.toId} · ${esc(milestoneName(e.toId))}</button></div><h3>Why this arrow exists</h3><p>${esc(e.rationale)}</p><h3>What it does not establish</h3><div class="uncertainty"><p>${esc(e.uncertainty)}</p></div><h3>Confidence and review</h3><p>${esc(e.confidence)} conceptual confidence. ${esc(e.confidenceMeaning)}</p><p>${esc(e.provenance.review)}</p><h3>Exact source trace</h3><p>${esc(e.provenance.origin)}</p>${e.provenance.sourceMilestones.map(p=>`<div class="edge-source"><b>${p.id} / ${esc(p.workbook)} · ${p.sheet} row ${p.row}</b><p>${esc(p.description)}</p></div>`).join('')}${e.alternativeGroup?`<h3>Alternative approach group</h3><p>${esc(e.alternativeGroup)}. These approaches can combine; no route is asserted sufficient for success.</p>`:''}${e.resultIds.length?`<h3>Contextual checked research</h3><p>These findings inform relevance; they do not prove this dependency.</p>${e.resultIds.map(id=>{const r=data.results.find(r=>r.id===id);return `<div class="edge-source">${link(r.source.url,esc(r.source.title)+' ↗','source-link')}<p>${esc(r.claim)}</p><p>Limits: ${esc(r.limitations)}</p><p>${esc(r.source.dateLabel)} · ${r.source.published}</p></div>`}).join('')}`:'<p class="source-assertion-note">No checked paper is claimed as direct support for this relationship. Its provenance is an editorial interpretation of the two source descriptions.</p>'}</div>`;}
function treeNodeDetail(){const review=tree.connectionReviews?.find(r=>r.milestoneId===selectedMilestone);const incident=tree.edges.filter(e=>e.fromId===selectedMilestone||e.toId===selectedMilestone);return `<div class="node-connection-summary"><span class="eyebrow">SELECTED MILESTONE / TREE CONNECTIONS</span><p>${review?`Review disposition: ${esc(review.disposition)}. ${esc(review.reason)}<br><br>`:''}${incident.length?`${incident.length} proposed arrows. Select one to inspect its mechanism and limitations.`:'Not yet connected in the curated tree. The recorded reason explains the unresolved connection; no scientific independence is implied.'}</p><button class="secondary" id="show-lineage">Explore upstream + downstream →</button>${incident.map(e=>`<button class="incident-edge" data-edge="${e.id}"><span>${e.fromId===selectedMilestone?'OUT →':'← IN'} ${e.fromId===selectedMilestone?e.toId:e.fromId}</span>${treeTypeLabel[e.kind]} <small>Hypothesis · ${e.confidence}</small></button>`).join('')}</div>${originalDetail()}`;}
function directedTreeView(){
 const v=activeTreeView(),layout=layoutTree(v),ancestors=lineage(tree,selectedMilestone,'upstream'),descendants=lineage(tree,selectedMilestone,'downstream'),inView=new Set(v.nodes.map(n=>n.id));
 const title=treeFocus?`${treeFocus} / focused lineage`:treeField?`${treeField} / connected branch`:tree.branches.find(b=>b.id===treeBranch).title;
 const searched=treeQuery?collection.milestones.filter(n=>[n.id,n.title,n.field].join(' ').toLowerCase().includes(treeQuery.toLowerCase())).slice(0,12):[];
 const path=e=>{const a=layout.positions.get(e.fromId),b=layout.positions.get(e.toId),x=a.x+a.width,y=a.y+a.height/2,x2=b.x,y2=b.y+b.height/2;if(e.kind==='feedback'){const fx=a.x+a.width/2,tx=b.x+b.width/2,top=Math.min(a.y,b.y)-65;return `M${fx},${a.y} C${fx},${top} ${tx},${top} ${tx},${b.y}`;}return `M${x},${y} C${x+55},${y} ${x2-55},${y2} ${x2},${y2}`;};
 const cols=[...new Set([...layout.layers.values()])].sort((a,b)=>a-b);
 return `<main class="workspace directed-workspace"><div class="toolbar tree-toolbar"><div class="collection-title"><span class="eyebrow">A TREE OF YOUR ORIGINAL MILESTONES</span><strong>${esc(title)}</strong></div><div class="tree-search"><label class="searchbox"><span aria-hidden="true">⌕</span><input id="tree-search" aria-label="Find any of 660 milestones" placeholder="Find any milestone or ID…" value="${esc(treeQuery)}" autocomplete="off"></label>${treeQuery?`<div class="tree-search-results">${searched.length?searched.map(n=>`<button data-tree-jump="${n.id}"><span>${n.id} / ${esc(n.field)} · ${treeConnected.has(n.id)?'Connected':'Not yet connected'}</span>${esc(n.title)}</button>`).join(''):'<p>No milestones match.</p>'}</div>`:''}</div></div>
 <div class="directed-layout"><aside class="branch-sidebar"><span class="eyebrow">EXPLORE A BRANCH</span><div class="branch-list">${tree.branches.map(b=>`<button data-branch="${b.id}" class="${!treeField&&!treeFocus&&treeBranch===b.id?'active':''}"><span>${esc(b.title)}</span><small>${b.nodeIds.length}</small></button>`).join('')}</div><label class="tree-field-label">Or choose any field<select id="tree-field"><option value="">All 66 fields available</option>${collection.fields.map(f=>`<option value="${esc(f.name)}" ${treeField===f.name?'selected':''}>${esc(f.name)} · ${collection.milestones.filter(n=>n.field===f.name&&treeConnected.has(n.id)).length}/${f.count} connected</option>`).join('')}</select></label><div class="tree-coverage"><strong>${treeConnected.size} / 660</strong><span>Milestones connected in this tree</span><strong>${tree.edges.length} arrows / ${new Set(collection.milestones.filter(m=>treeConnected.has(m.id)).map(m=>m.field)).size} fields</strong><span>All editorial hypotheses.<br>${tree.reviewSummary?`${tree.reviewSummary.reviewed}/546 reviewed this pass.<br>`:''}${660-treeConnected.size} milestones not yet connected.<br>No established required dependency asserted.</span></div>${proofProgress(sourceAudit)}</aside>
 <section class="tree-main"><div class="tree-viewbar"><span>${v.nodes.length} NODES · ${v.edges.length} ARROWS</span><div class="tree-view-options"><select id="tree-type" aria-label="Filter relationship type"><option value="all">All proposed links</option>${['enabling','accelerator','alternative-route','feedback'].map(t=>`<option value="${t}" ${treeFilter===t?'selected':''}>${treeTypeLabel[t]}</option>`).join('')}</select>${treeFocus?`<select id="tree-depth" aria-label="Lineage depth"><option value="1" ${treeDepth===1?'selected':''}>Direct connections</option><option value="2" ${treeDepth===2?'selected':''}>Two steps</option><option value="all" ${treeDepth==='all'?'selected':''}>Full lineage</option></select>`:''}</div></div>${v.omittedNodes?`<p class="tree-disclosure">${v.omittedNodes} contextual milestones omitted to keep this view readable. Search any milestone to explore its connections.</p>`:''}<div class="tree-disclosure"><i class="dot"></i>Arrows are proposed mechanisms, not established prerequisites or a promised chronology. Select an arrow to inspect why.</div>
 <div class="graph-viewport" id="graph-viewport" tabindex="0" aria-label="Directed technology tree. Drag to pan. Use zoom and fit controls."><div class="graph-stage" id="graph-stage" style="width:${layout.width}px;height:${layout.height}px;transform:translate(${treeCamera.x}px,${treeCamera.y}px) scale(${treeCamera.z})">${cols.map(col=>`<span class="graph-layer" style="left:${45+col*355}px;top:12px">${col===0?'UPSTREAM CAPABILITIES':col===cols.at(-1)?'DOWNSTREAM USES':`PARALLEL PATHWAYS / ${col}`}</span>`).join('')}
 <svg class="graph-wires" width="${layout.width}" height="${layout.height}" aria-label="Proposed milestone relationships"><defs>${['enabling','accelerator','alternative-route','feedback'].map(t=>`<marker id="tree-arrow-${t}" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M1 1L8 4.5L1 8" fill="none" stroke="${t==='enabling'?'#a5cf8e':t==='accelerator'?'#a8b8c9':t==='feedback'?'#d7a6b7':'#d4b47e'}" stroke-width="1.4"/></marker>`).join('')}</defs>${v.edges.map(e=>{const highlighted=(ancestors.has(e.fromId)&&ancestors.has(e.toId))||(descendants.has(e.fromId)&&descendants.has(e.toId));return `<g class="graph-edge ${e.kind} ${highlighted?'highlighted':'muted'} ${selectedEdge===e.id?'selected-edge':''}" data-edge-id="${e.id}"><path class="graph-wire" d="${path(e)}" marker-end="url(#tree-arrow-${e.kind})"/><path class="edge-hit" d="${path(e)}" data-edge="${e.id}" role="button" tabindex="0" aria-label="${e.fromId} to ${e.toId}: ${treeTypeLabel[e.kind]}, editorial hypothesis"/><title>${esc(e.rationale)}</title></g>`}).join('')}</svg>
 ${v.nodes.map(n=>{const p=layout.positions.get(n.id),up=ancestors.has(n.id)&&n.id!==selectedMilestone,down=descendants.has(n.id)&&n.id!==selectedMilestone;return `<button class="tree-node ${n.id===selectedMilestone?'selected':''} ${n.id===selectedMilestone?'':up?'upstream':down?'downstream':'unrelated'} ${treeConnected.has(n.id)?'':'not-connected'}" data-tree-node="${n.id}" style="left:${p.x}px;top:${p.y}px;width:${p.width}px;height:${p.height}px;--accent:${treeNodeColor(n)}" aria-pressed="${n.id===selectedMilestone}" title="${esc(n.title)}" aria-label="${n.id}: ${esc(n.title)}. Original proposed milestone."><span class="tree-node-meta"><b>${n.id}</b><span>${esc(n.field)}</span></span><span class="tree-node-title">${esc(n.title)}</span><span class="tree-node-state">${!treeConnected.has(n.id)?'Not yet connected':n.id===selectedMilestone?'Selected · original proposal':up?'Upstream · proposed relationship':down?'Downstream · proposed relationship':'Original proposed milestone'}</span></button>`}).join('')}
 ${!v.nodes.length?'<div class="empty-graph"><h2>This field is not connected yet.</h2><p>Its original milestones are available below. No arrows are drawn until relationships are reviewed.</p></div>':''}</div><div class="graph-pan-hint">DRAG TO PAN · SCROLL TO ZOOM · SELECT A NODE OR ARROW</div></div>
 <div class="graph-footer"><div class="tree-legend"><span><i class="line-enabling"></i>Enabling component</span><span><i class="line-accelerator"></i>Accelerator</span><span><i class="line-alternative"></i>Alternative approach</span><span><i class="line-feedback"></i>Feedback</span></div><div class="tree-zoom"><button id="tree-zoom-out" aria-label="Zoom tree out">−</button><span id="tree-zoom-label">${Math.round(treeCamera.z*100)}%</span><button id="tree-zoom-in" aria-label="Zoom tree in">＋</button><button id="tree-fit">Fit tree</button><button id="tree-reset">Reset</button></div></div>
 ${v.unmapped.length?`<section class="unmapped-tray"><h3>${v.unmapped.length} original milestones not yet connected</h3><p>These are mapping gaps, not conclusions that the milestones have no prerequisites.</p>${v.unmapped.map(n=>`<button data-tree-jump="${n.id}"><b>${n.id}</b> ${esc(n.title)} ↗<small>${esc(tree.connectionReviews?.find(r=>r.milestoneId===n.id)?.reason||'Not reviewed in this connection pass yet.')}</small></button>`).join('')}</section>`:''}${v.outside.length?`<section class="unmapped-tray"><h3>Connected elsewhere in the tree</h3>${v.outside.map(n=>`<button data-tree-jump="${n.id}">${n.id} / ${esc(n.title)} ↗</button>`).join('')}</section>`:''}</section>
 <aside class="detail tree-detail" aria-label="Tree reasoning and original milestone details">${selectedEdge?treeEdgeDetail():treeNodeDetail()}</aside></div></main>`;
}
function bindDirectedTree(){if(tab!=='tree')return;
 const v=activeTreeView(),layout=layoutTree(v),viewport=$('#graph-viewport'),stage=$('#graph-stage');
 function camera(){stage.style.transform=`translate(${treeCamera.x}px,${treeCamera.y}px) scale(${treeCamera.z})`;$('#tree-zoom-label').textContent=`${Math.round(treeCamera.z*100)}%`;stage.classList.toggle('zoomed-out',treeCamera.z<.8);}
 function fit(){const w=viewport.clientWidth,h=viewport.clientHeight,z=Math.min(1,Math.max(.15,Math.min((w-50)/layout.width,(h-55)/layout.height)));treeCamera={z,x:(w-layout.width*z)/2,y:(h-layout.height*z)/2};camera();}
 function zoom(factor,x=viewport.clientWidth/2,y=viewport.clientHeight/2){const old=treeCamera.z,z=Math.max(.15,Math.min(2.5,old*factor));treeCamera.x=x-(x-treeCamera.x)*z/old;treeCamera.y=y-(y-treeCamera.y)*z/old;treeCamera.z=z;camera();}
 if(treeNeedFit){fit();treeNeedFit=false;}else camera();
 document.querySelectorAll('[data-branch]').forEach(b=>b.onclick=()=>{treeBranch=b.dataset.branch;treeField=null;treeFocus=null;treeFilter='all';treeQuery='';selectedEdge=null;const bch=tree.branches.find(b=>b.id===treeBranch);if(!bch.nodeIds.includes(selectedMilestone))selectedMilestone=bch.nodeIds.find(id=>tree.edges.some(e=>e.toId===id))||bch.nodeIds[0];treeNeedFit=true;render()});
 $('#tree-field').onchange=e=>{if(!e.target.value)return;treeField=e.target.value;treeFocus=null;treeFilter='all';selectedEdge=null;const ns=collection.milestones.filter(n=>n.field===treeField);selectedMilestone=ns.find(n=>treeConnected.has(n.id))?.id||ns[0].id;treeNeedFit=true;render()};
 $('#tree-search').oninput=e=>{const position=e.target.selectionStart;treeQuery=e.target.value;render();$('#tree-search').focus();$('#tree-search').setSelectionRange(position,position)};
 document.querySelectorAll('[data-tree-jump]').forEach(b=>b.onclick=()=>{treeQuery='';openTreeNode(b.dataset.treeJump,{lineageView:true})});
 document.querySelectorAll('[data-tree-node]').forEach(b=>b.onclick=()=>openTreeNode(b.dataset.treeNode));
 document.querySelectorAll('[data-edge]').forEach(b=>{const select=()=>{selectedEdge=b.dataset.edge;render()};b.onclick=select;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}});
 if($('#show-lineage'))$('#show-lineage').onclick=()=>openTreeNode(selectedMilestone,{lineageView:true});if($('#close-edge'))$('#close-edge').onclick=()=>{selectedEdge=null;render()};
 $('#tree-type').onchange=e=>{treeFilter=e.target.value;treeNeedFit=true;render()};if($('#tree-depth'))$('#tree-depth').onchange=e=>{treeDepth=e.target.value==='all'?'all':Number(e.target.value);treeNeedFit=true;render()};
 $('#tree-zoom-in').onclick=()=>zoom(1.2);$('#tree-zoom-out').onclick=()=>zoom(1/1.2);$('#tree-fit').onclick=fit;$('#tree-reset').onclick=()=>{treeCamera={x:20,y:20,z:1};camera()};
 viewport.onwheel=e=>{e.preventDefault();const rect=viewport.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.0015),e.clientX-rect.left,e.clientY-rect.top)};
 let drag=null;viewport.onpointerdown=e=>{if(e.target.closest('button,[data-edge],input,select,a'))return;drag={x:e.clientX,y:e.clientY,cx:treeCamera.x,cy:treeCamera.y};viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging')};viewport.onpointermove=e=>{if(!drag)return;treeCamera.x=drag.cx+e.clientX-drag.x;treeCamera.y=drag.cy+e.clientY-drag.y;camera()};viewport.onpointerup=()=>{drag=null;viewport.classList.remove('dragging')};viewport.onpointercancel=viewport.onpointerup;
 viewport.onkeydown=e=>{if(e.target!==viewport)return;const offsets={ArrowLeft:[-40,0],ArrowRight:[40,0],ArrowUp:[0,-40],ArrowDown:[0,40]};if(offsets[e.key]){e.preventDefault();treeCamera.x+=offsets[e.key][0];treeCamera.y+=offsets[e.key][1];camera();}if(e.key==='+'||e.key==='=')zoom(1.2);if(e.key==='-')zoom(1/1.2);if(e.key==='0')fit();};
}

function migrationReportView(){if(!migrationStatus.snapshots.length)return '<p class="source-assertion-note">No browser saves have been found in this browser. Existing saves in another browser are checked when that browser opens this site at the same address.</p>';return `<details class="migration-report"><summary>Browser-save migration / ${migrationStatus.snapshots.length} preserved snapshots${migrationStatus.conflicts.length?` / ${migrationStatus.conflicts.length} conflicts need review`:''}</summary><p>Original browser storage is never cleared. Raw snapshots and conflicting records are retained in the database export and SQLite backup. Conflicts are not overwritten or silently approved.</p>${migrationStatus.snapshots.map(s=>`<p><b>${esc(s.key)}</b><br>${s.report.added} submissions imported · ${s.report.legacyRecords} legacy records imported · ${s.report.conflicts} conflicts${s.report.issues.length?`<br>${s.report.issues.map(esc).join('<br>')}`:''}</p>`).join('')}${migrationStatus.conflicts.map(c=>`<div class="history-card"><b>${esc(c.record_id||'Saved record')}</b><p>${esc(c.reason)}</p><details><summary>Preserved conflicting record</summary><pre>${esc(JSON.stringify(c.payload,null,2))}</pre></details></div>`).join('')}</details>`;}
function databaseActivityView(){return `<p>SQLite revision records: ${dbActivity.revisions.length}. Recorded review events: ${dbActivity.reviews.length}. Historical prototype imports are unverified archival records.</p><div class="timeline">${dbActivity.revisions.filter(r=>r.scope!=='collection').map(r=>`<article class="history-card"><span class="eyebrow">${esc(r.scope)}</span><h3>${esc(r.payload.title||'Preserved historical revision')}</h3><p>${esc(r.payload.description||'Original historical record retained without applying its scientific claims.')}<br>${esc(r.created_at)}</p></article>`).join('')}${dbActivity.reviews.map(r=>`<article class="history-card"><span class="eyebrow">${esc(r.action)}</span><p>${esc(r.submission_id||'Unverified legacy review')} · ${esc(r.created_at)}</p></article>`).join('')}</div>`;}

function render(){
 document.title=tab==='tree'?'TechTree — The technology tree':'TechTree — Original milestone collection';
 const pending=desk.submissions.filter(s=>s.state==='pending-source-review').length;
 $('#app').innerHTML=`${storageError?`<div class="banner">${esc(storageError)} <button id="raw-export">Export retained save</button></div>`:''}<header><button class="brand" data-tab="tree" aria-label="TechTree home"><svg viewBox="0 0 32 38" fill="none" aria-hidden="true"><path d="M16 35V18M16 20L3 7M16 20L29 7M16 29L5 19M16 29L27 19" stroke="currentColor" stroke-width="2"/><circle cx="3" cy="6" r="2" fill="currentColor"/><circle cx="29" cy="6" r="2" fill="currentColor"/></svg>TechTree <small>A LIVING TECHNOLOGY MAP</small></button><nav aria-label="Main navigation">${[['tree','The tree'],['milestones','Collection'],['sources','Evidence'],['changes','History'],['desk',`Research desk${pending?` (${pending})`:''}`]].map(([id,name])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${name}</button>`).join('')}</nav><div class="header-end"><span class="live"><i></i>Original ideas · scoped evidence</span><button class="primary" id="suggest">＋ Suggest a source</button></div></header>
 <section class="hero"><div><span class="eyebrow">YOUR ORIGINAL MILESTONES / A FIRST CONNECTED TREE</span><h1>What comes next. <em>And what connects.</em></h1><p>Trace proposed upstream capabilities, parallel approaches and downstream uses.<br>Select any arrow to inspect its mechanism, uncertainty and source trace.</p></div><div class="hero-stats"><div class="stat"><strong>${treeConnected.size}</strong><span>Milestones connected</span></div><div class="stat"><strong>${tree.edges.length}</strong><span>Proposed arrows</span></div><div class="stat"><strong>660</strong><span>Original milestones</span></div></div></section>
 ${tab==='tree'?directedTreeView():tab==='milestones'?collectionView():tab==='sources'?sourcesView():tab==='changes'?collectionHistory():deskView()}
 <footer class="footer"><span>TECHTREE / Read the evidence. Keep its limits in view.</span><span>Milestones are proposals. Evidence has a scope.</span></footer><dialog id="source-dialog"></dialog>`;
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$('#suggest').onclick=showSuggestion;
 if($('#raw-export'))$('#raw-export').onclick=()=>download({snapshots:retainedBrowserSnapshots},'techtree-retained-browser-saves.json');
 bind();collectionBind();bindDirectedTree();
}
function atlasView(){
 const visible=filterResults(data,{domain,query,kind});const groups=layout==='grouped'?data.domains.map(d=>({domain:d,results:visible.filter(r=>r.domain===d)})).filter(g=>g.results.length):[{domain:'All results',results:visible}];
 return `<main class="workspace evidence-workspace"><div class="toolbar"><div class="filters" aria-label="Filter fields" role="group">${['All fields',...data.domains].map(d=>`<button data-domain="${d}" class="chip ${domain===d?'active':''}" style="--accent:${colors[d]||'var(--green)'}">${d!=='All fields'?'<i class="dot"></i>':''}${d==='AI'?'Artificial intelligence':d}</button>`).join('')}</div><div class="tools"><label class="searchbox"><span aria-hidden="true">⌕</span><input id="search" aria-label="Search results and sources" placeholder="Search findings or sources…" value="${esc(query)}"></label><select id="kind-filter" aria-label="Filter study type"><option value="all">All study types</option>${[...new Set(data.results.map(r=>r.kind))].map(k=>`<option ${kind===k?'selected':''} value="${k}">${k}</option>`).join('')}</select></div></div>
 <div class="atlas-note"><span><i class="dot"></i><b>${visible.length} ${visible.length===1?'RESULT':'RESULTS'}</b> · GROUPED BY FIELD</span><span>No dependency arrows: these papers do not establish causal prerequisites.</span></div><div class="evidence-layout"><section class="findings" aria-label="Source-supported findings">${visible.length?groups.map(group=>`<section class="field-section" style="--accent:${colors[group.domain]||'var(--green)'}"><div class="field-heading"><div><span class="field-symbol">${icons[group.domain]||'✳'}</span><h2>${group.domain==='AI'?'Artificial intelligence':group.domain}</h2></div><span>${group.results.length.toString().padStart(2,'0')} REPORTED ${group.results.length===1?'RESULT':'RESULTS'}</span></div><div class="result-grid">${group.results.map(card).join('')}</div></section>`).join(''):'<div class="empty">No results match these filters.<br><br><button class="secondary" id="clear">Clear filters</button></div>'}</section><aside class="detail evidence-detail" aria-label="Selected finding details">${detailView()}</aside></div></main><section class="insight-strip"><span class="insight-mark">↳</span><div><h3>A finding has a scope. A source makes it inspectable.</h3><p>This selection describes what the cited studies report. It is not a review of every later study, an independent replication, or a roadmap promising future capabilities. No forecast dates or hypothetical dependencies are displayed.</p></div><button data-tab="changes">See what was corrected ↗</button></section>`;
}
function detailView(){
 const r=data.results.find(r=>r.id===selected)||data.results[0],s=r.source;
 return `<div class="detail-inner" style="--accent:${colors[r.domain]}"><div class="detail-top"><span>${r.domain.toUpperCase()} / ${r.id}</span><span>↗</span></div><h2>${esc(r.title)}</h2><span class="badge"><i class="status-dot"></i>Reported result · scoped</span><h3>Supported claim</h3><p class="criteria">${esc(r.claim)}</p><h3>Experimental setting</h3><p>${esc(r.scope)}</p><h3>What this does not establish</h3><div class="uncertainty"><p>${esc(r.limitations)}</p></div>${sourceBlock(r)}<h3>Where to check</h3><p>${esc(s.locator)}</p><h3>What was reviewed</h3><p>${esc(s.checkMethod)}</p><p class="check-stamp">Checked ${shortDate(s.checkedAt)}<br>${esc(s.accessNote)}</p><div class="detail-bottom"><span class="card-label">NO CAUSAL DEPENDENCIES ASSERTED</span><p>A related paper does not demonstrate that one capability is necessary or sufficient for another. This view draws no dependency edges.</p></div></div>`;
}
function sourcesView(){return `<main class="page-content"><div class="view-actions"><span class="eyebrow">CHECKED DESTINATIONS + CLAIM SCOPE</span><button class="secondary" id="export-evidence">Export evidence record</button></div><p>For each displayed result, the linked primary abstract or article was opened and the summary checked against the cited passage. Review depth is stated below. This does not independently reproduce the experiments or establish scientific consensus.</p><div class="source-check-list">${data.results.map(r=>`<article class="history-card" style="--accent:${colors[r.domain]}"><div class="revision-head"><div><span class="eyebrow">${r.domain} / ${r.id}</span><h3>${esc(r.title)}</h3></div><button class="secondary" data-open="${r.id}">View original milestone ↗</button></div><div class="source-check-content"><div><h4>Supported claim</h4><p>${esc(r.claim)}</p><h4>Limits</h4><p>${esc(r.limitations)}</p><h4>Attached original milestones</h4>${collection.evidenceAssociations.filter(a=>a.resultId===r.id).map(a=>`<button class="detail-evidence-link" data-jump="${a.milestoneId}">${a.milestoneId} / ${esc(milestoneName(a.milestoneId))} ↗</button>`).join('')}</div><div>${sourceBlock(r)}<p><b>Passage:</b> ${esc(r.source.locator)}<br><b>Review:</b> ${esc(r.source.checkMethod)}<br><b>Checked:</b> ${shortDate(r.source.checkedAt)}</p></div></div></article>`).join('')}</div></main>`;}
function changesView(){const a=data.audit;return `<main class="page-content"><span class="eyebrow">CORRECTION RECORD / ${shortDate(data.checkedAt)}</span><h2 class="section-title">From possibilities to inspectable results.</h2><p>The initial prototype mixed experimental results with editorial aspirations, invented success thresholds and unsupported future windows. That was misleading. This version removes those elements from the website and starts with scoped research claims.</p><div class="coverage-table"><table><thead><tr><th>Coverage</th><th>Previous prototype</th><th>Current evidence view</th></tr></thead><tbody>${[['Cards / results',24,9],['Fields',4,4],['Future windows',19,0],['Invented success criteria',24,0],['Dependency routes',16,0],['Dependency / accelerator arrows',29,0]].map(row=>`<tr>${row.map((v,i)=>i===0?`<th scope="row">${v}</th>`:`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="history-card"><span class="eyebrow">WHAT CHANGED</span><ul>${a.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p>The current claims are drawn from nine of the original eleven referenced publications. Some publications now have a dedicated result card; these were already cited in the prototype. No field expansion has occurred.</p></div><h3 class="subheading">Sources omitted from the evidence view</h3><div class="cards">${a.excluded.map(s=>`<article class="evidence-card"><h3>${esc(s.title)}</h3><p>${esc(s.reason)}</p>${link(s.sourceUrl,'Inspected source destination ↗')}<p>Checked ${shortDate(s.checkedAt)}</p></article>`).join('')}</div><h3 class="subheading">Preserved history</h3><p>Original documents and the previous graph are retained on disk outside the served site. Earlier browser proposals remain under the prototype’s original storage key and are never promoted into this evidence view.</p><button class="secondary" id="export-legacy">Export previous browser proposals</button><h3 class="subheading">Validation limits</h3><p>${esc(a.policy)} Abstract-level checks cover CLIP, GNS, RT-2 and Diffusion Policy. Additional source sections were checked for the other five results. No complete literature, replication or research-integrity audit has been performed. The findings span older publications; this is not a complete account of progress through 2026.</p></main>`;}
function deskView(){return `<main class="page-content"><div class="view-actions"><span class="eyebrow">SOURCE SUGGESTIONS / AWAITING REVIEW</span><button class="secondary" id="export-desk">Export research desk</button><a class="secondary" href="/api/backup" download>Back up SQLite</a><button class="secondary" id="export-database">Export all saved data</button></div><p>Suggestions are saved in local SQLite and stay separate from the evidence atlas. Pasting a link does not verify its contents. This browser cannot approve a claim into the atlas; primary-source checking and a reviewed dataset change are required.</p>${migrationReportView()}${desk.submissions.length?`<div class="timeline">${[...desk.submissions].reverse().map(s=>`<article class="history-card"><span class="eyebrow">${s.state==='dismissed'?'DISMISSED':'UNVERIFIED · AWAITING SOURCE REVIEW'}</span><h3>${esc(s.title)}</h3>${s.milestoneId?`<button class="detail-evidence-link" data-jump="${esc(s.milestoneId)}">Suggested milestone: ${esc(s.milestoneId)} / ${esc(milestoneName(s.milestoneId))}</button>`:''}<p><b>Submitter’s summary:</b> ${esc(s.summary)}<br><b>Stated limits:</b> ${esc(s.limits)}</p>${link(s.url,esc(s.url),'source-url')}${s.state==='pending-source-review'?`<div class="proposal-actions"><button class="secondary" data-dismiss="${s.id}">Dismiss suggestion</button></div>`:''}</article>`).join('')}</div>`:'<div class="empty">No source suggestions yet.<br><br>Use “Suggest a source” to save research for checking.</div>'}</main>`;}
function bind(){
 document.querySelectorAll('[data-domain]').forEach(b=>b.onclick=()=>{domain=b.dataset.domain;const matches=filterResults(data,{domain,query,kind});if(matches.length&&!matches.some(r=>r.id===selected))selected=matches[0].id;render()});
 if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;const matches=filterResults(data,{domain,query,kind});if(matches.length&&!matches.some(r=>r.id===selected))selected=matches[0].id;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};
 if($('#kind-filter'))$('#kind-filter').onchange=e=>{kind=e.target.value;const matches=filterResults(data,{domain,query,kind});if(matches.length)selected=matches[0].id;render()};
 document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;const scroll=window.scrollY;render();window.scrollTo(0,scroll)});
 document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const a=collection.evidenceAssociations.find(a=>a.resultId===b.dataset.open);if(a)jumpMilestone(a.milestoneId,'map');window.scrollTo(0,0)});
 if($('#clear'))$('#clear').onclick=()=>{domain='All fields';query='';kind='all';render()};
 if($('#export-evidence'))$('#export-evidence').onclick=()=>download(data,'techtree-evidence-record.json');
 if($('#export-desk'))$('#export-desk').onclick=()=>download(desk,'techtree-source-suggestions.json');
 if($('#export-database'))$('#export-database').onclick=async()=>{try{download(await api('/api/export'),'techtree-database-export.json')}catch(e){toast(e.message)}};
 if($('#export-legacy'))$('#export-legacy').onclick=()=>{try{download({notice:'Unreviewed earlier prototype data. Not part of the evidence atlas.',raw:localStorage.getItem('techtree-state-v1')},'techtree-earlier-prototype-proposals.json')}catch(e){toast(e.message)}};
 document.querySelectorAll('[data-dismiss]').forEach(b=>b.onclick=async()=>{const item=desk.submissions.find(s=>s.id===b.dataset.dismiss);b.disabled=true;try{await api('/api/submissions/'+encodeURIComponent(item.id),{method:'PATCH',body:JSON.stringify({state:'dismissed',version:item.version})});await refreshDesk();render();toast('Suggestion dismissed in SQLite. Evidence unchanged.')}catch(error){await refreshDesk().catch(()=>{});render();toast(error.message)}});
}
function showSuggestion(){const dlg=$('#source-dialog');dlg.innerHTML=`<div class="modal-head"><div><span class="eyebrow">RESEARCH DESK</span><h2>Suggest a primary source</h2></div><button id="close-modal" aria-label="Close source form">×</button></div><div class="modal-body"><p>This saves an unverified suggestion. It will not change the evidence atlas. Links are not fetched or checked automatically.</p><form id="source-form"><label>Related original milestone (optional)<select name="milestoneId"><option value="">Not assigned</option>${collection.milestones.map(m=>`<option value="${m.id}" ${selectedMilestone===m.id?'selected':''}>${m.id} / ${esc(m.title)}</option>`).join('')}</select></label><label>Research title<input name="title" required maxlength="180"></label><label>Primary paper or source URL<input type="url" name="url" required placeholder="https://…" maxlength="2000"></label><label>What does the source actually report?<textarea name="summary" required maxlength="12000"></textarea></label><label>Experimental setting and limitations<textarea name="limits" required maxlength="12000"></textarea></label><p class="error" id="form-error" role="alert"></p><div class="form-actions"><small>Saved in the local SQLite database.</small><button type="submit" class="primary">Save for source review →</button></div></form></div>`;$('#close-modal').onclick=()=>dlg.close();const draftId=crypto.randomUUID(),draftCreatedAt=new Date().toISOString();$('#source-form').onsubmit=async e=>{e.preventDefault();try{const form=new FormData(e.target);const item=proposal({id:draftId,title:form.get('title'),url:form.get('url'),summary:form.get('summary'),limits:form.get('limits'),milestoneId:form.get('milestoneId'),createdAt:draftCreatedAt});const {state,...newItem}=item;await api('/api/submissions',{method:'POST',body:JSON.stringify(newItem)});await refreshDesk();dlg.close();tab='desk';render();toast('Saved to SQLite as unverified. The evidence atlas is unchanged.')}catch(e){$('#form-error').textContent=e.message}};dlg.showModal();}
render();

// Refresh only the evidence layer while research batches are completed.
setInterval(async()=>{try{const next=await api('/api/source-audit');if(JSON.stringify(next.summary)!==JSON.stringify(sourceAudit?.summary)){sourceAudit=next;const scroll=window.scrollY;render();window.scrollTo(0,scroll);}}catch{/* Keep the last read state; never promote missing data. */}},60000);
